fn phase5b_dir() -> PathBuf {
    fixture_dir().join("phase5b")
}

fn load_json<T: DeserializeOwned>(name: &str) -> T {
    let path = phase5b_dir().join(name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "{}: {e}; run scripts/generate_fixtures.py --phase 5b",
            path.display()
        )
    });
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

/// The per-model fixtures (sorted by name).
fn load() -> Vec<Fixture> {
    let mut names: Vec<String> = std::fs::read_dir(phase5b_dir())
        .expect("phase-5b fixture directory exists")
        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
        .filter(|n| n.ends_with(".json") && n != "misc.json" && !n.starts_with("pending"))
        .collect();
    names.sort();
    assert!(names.len() >= 4, "phase-5b fixtures are missing");
    names.iter().map(|n| load_json(n)).collect()
}

// ---------------------------------------------------------------------------
// Builders
// ---------------------------------------------------------------------------

fn build_member(f: &ModelSpec) -> BatchedMultiOutputGP {
    let c = &f.config;
    let x: Vec<Matrix> = f.train_x.iter().map(|b| matrix(b)).collect();
    let y: Vec<Matrix> = f.train_y.iter().map(|b| matrix(b)).collect();
    let mut options = BatchedMultiOutputGPOptions {
        train_yvar: f
            .train_yvar
            .as_ref()
            .map(|v| v.iter().map(|b| matrix(b)).collect()),
        ..Default::default()
    };
    match c.covar.as_str() {
        "rbf" => {}
        "matern" => options.kernel = KernelKind::Matern52,
        other => panic!("unknown covar {other}"),
    }
    options.input_transform = match c.normalize.as_deref() {
        None => None,
        Some("shared") => Some(BatchedInputTransform::Shared(Normalize::new(c.d))),
        Some("explicit") => Some(BatchedInputTransform::Shared(
            Normalize::with_bounds(&matrix(c.bounds.as_ref().unwrap())).unwrap(),
        )),
        Some(other) => panic!("unknown normalize {other}"),
    };
    if c.outcome == "none" {
        options.outcome_transform = OutcomeTransformChoice::None;
    }
    let mut model = BatchedMultiOutputGP::new(x, y, vec![], options).unwrap();
    assert_eq!(model.num_outputs(), c.m);
    model.set_raw_parameters(&f.raw_params).unwrap();
    model
}

fn build_model(kind: &str, specs: &[ModelSpec]) -> Arc<dyn Model> {
    let members: Vec<BatchedMultiOutputGP> = specs.iter().map(build_member).collect();
    match kind {
        "single_task" => Arc::new(members.into_iter().next().unwrap()),
        "model_list" => Arc::new(ModelListGP::new(members).unwrap()),
        other => panic!("unknown kind {other}"),
    }
}

/// A sampler with BoTorch's recorded base samples.
fn sampler(draws: &[Draw], num_samples: usize) -> Arc<SobolQMCNormalSampler> {
    let s = SobolQMCNormalSampler::new(num_samples, Some(UNRECORDED_SEED)).unwrap();
    for d in draws {
        s.set_base_samples(Matrix::from_row_slice(num_samples, d.d, &d.z))
            .unwrap();
    }
    Arc::new(s)
}

/// `[c_k + Σ_j a_kj y_j + Σ_j b_kj y_j²]_k` (in torch's order) and its
/// row-major Jacobian.
fn generic(a: &[Vec<f64>], b: &[Vec<f64>], c: &[f64], y: &[f64]) -> (Vec<f64>, Vec<f64>) {
    let mut values = Vec::with_capacity(c.len());
    let mut jac = Vec::with_capacity(c.len() * y.len());
    for k in 0..c.len() {
        let s1: f64 = y.iter().zip(&a[k]).map(|(y, a)| y * a).sum();
        let s2: f64 = y.iter().zip(&b[k]).map(|(y, b)| y * y * b).sum();
        values.push(c[k] + s1 + s2);
        jac.extend(
            y.iter()
                .enumerate()
                .map(|(j, y)| a[k][j] + 2.0 * b[k][j] * y),
        );
    }
    (values, jac)
}

fn build_objective(
    spec: &ObjectiveSpec,
    model: &dyn Model,
    x_baseline: &Matrix,
) -> Arc<dyn McMultiOutputObjective> {
    match spec.clone() {
        ObjectiveSpec::Identity {
            outcomes,
            num_outcomes,
        } => Arc::new(IdentityMcMultiOutputObjective::new(Some(&outcomes), num_outcomes).unwrap()),
        ObjectiveSpec::Weighted {
            weights,
            outcomes,
            num_outcomes,
        } => Arc::new(
            WeightedMcMultiOutputObjective::new(
                Vector::from_vec(weights),
                outcomes.as_deref(),
                num_outcomes,
            )
            .unwrap(),
        ),
        ObjectiveSpec::Generic { a, b, c } => {
            Arc::new(GenericMcMultiOutputObjective::new(move |y| {
                generic(&a, &b, &c, y)
            }))
        }
        ObjectiveSpec::Feasibility { constraint_idcs } => Arc::new(
            FeasibilityWeightedMcMultiOutputObjective::new(
                model,
                x_baseline,
                &constraint_idcs,
                None,
            )
            .unwrap(),
        ),
    }
}

fn objective_of(
    spec: &Option<ObjectiveSpec>,
    model: &dyn Model,
    x_baseline: &Matrix,
) -> Option<Arc<dyn McMultiOutputObjective>> {
    spec.as_ref().map(|s| build_objective(s, model, x_baseline))
}

/// `c + Σ a_t y_t + Σ b_t y_t²` (in torch's order) and its gradient.
fn quadratic(a: &[f64], b: &[f64], c: f64, y: &[f64]) -> (f64, Vec<f64>) {
    let s1: f64 = y.iter().zip(a).map(|(y, a)| y * a).sum();
    let s2: f64 = y.iter().zip(b).map(|(y, b)| y * y * b).sum();
    let g = y
        .iter()
        .zip(a.iter().zip(b))
        .map(|(y, (a, b))| a + 2.0 * b * y)
        .collect();
    (c + s1 + s2, g)
}

fn build_constraint(spec: &ConstraintSpec) -> Arc<dyn McConstraint> {
    match spec.clone() {
        ConstraintSpec::Linear { weights, offset } => {
            Arc::new(LinearOutcomeConstraint::new(Vector::from_vec(weights), offset).unwrap())
        }
        ConstraintSpec::Quadratic { a, b, c } => {
            Arc::new(FnOutcomeConstraint::new(move |y| quadratic(&a, &b, c, y)))
        }
    }
}

fn constraints_of(
    specs: &Option<Vec<ConstraintSpec>>,
    eta: &Option<Vec<f64>>,
) -> Option<OutcomeConstraints> {
    specs.as_ref().map(|cs| {
        OutcomeConstraints::new(
            cs.iter().map(build_constraint).collect(),
            eta.clone().expect("eta"),
        )
        .unwrap()
    })
}

fn partitioning(
    kind: &str,
    ref_point: &[f64],
    front: &Matrix,
    alpha: f64,
) -> Box<dyn BoxDecomposition> {
    match kind {
        "fast" => Box::new(FastNondominatedPartitioning::new(ref_point, Some(front)).unwrap()),
        "nondominated" => {
            Box::new(NondominatedPartitioning::new(ref_point, Some(front), alpha).unwrap())
        }
        other => panic!("unknown partitioning {other}"),
    }
}

// ---------------------------------------------------------------------------
// Comparisons
// ---------------------------------------------------------------------------

/// Values and gradients (row-major) of the t-batch `x`; the values of
/// `forward_many` must equal those computed with gradients.
fn evaluate(acqf: &dyn AcquisitionFunction, x: &[Vec<Vec<f64>>]) -> (Vec<f64>, Vec<f64>) {
    let xs: Vec<Matrix> = x.iter().map(|b| matrix(b)).collect();
    let mut values = Vec::with_capacity(xs.len());
    let mut grads = Vec::new();
    for xb in &xs {
        let (v, g) = acqf.forward_with_grad(xb).unwrap();
        values.push(v);
        grads.extend(matrix_rows(&g));
    }
    let plain = acqf.forward_many(&xs).unwrap();
    for (a, b) in plain.iter().zip(&values) {
        assert!(
            (a - b).abs() <= 1e-13 * b.abs().max(1.0),
            "forward_many {a} differs from forward_with_grad {b}"
        );
    }
    (values, grads)
}

/// Error of log-space values: absolute below 1, relative above (`-inf`
/// must match).
fn log_err(a: &[f64], e: &[f64]) -> f64 {
    assert_eq!(a.len(), e.len());
    a.iter()
        .zip(e)
        .map(|(a, e)| {
            if a.is_infinite() || e.is_infinite() {
                if a == e {
                    0.0
                } else {
                    f64::INFINITY
                }
            } else {
                (a - e).abs() / e.abs().max(1.0)
            }
        })
        .fold(0.0, f64::max)
}

/// [`rel_err`] where entries within `atol` count as equal.
fn rel_err_atol(a: &[f64], e: &[f64], atol: f64) -> f64 {
    let a: Vec<f64> = a
        .iter()
        .zip(e)
        .map(|(&a, &e)| if (a - e).abs() <= atol { e } else { a })
        .collect();
    rel_err(&a, e)
}

/// Relative error of finite entries; non-finite entries must match.
fn finite_err(a: &[f64], e: &[f64]) -> f64 {
    assert_eq!(a.len(), e.len(), "length mismatch");
    let mut worst = 0.0f64;
    for (x, y) in a.iter().zip(e) {
        if !x.is_finite() || !y.is_finite() {
            if x != y {
                return f64::INFINITY;
            }
            continue;
        }
        worst = worst.max((x - y).abs() / y.abs().max(1.0));
    }
    worst
}

#[allow(clippy::too_many_arguments)]
fn compare(
    r: &mut Report,
    fixture: &str,
    label: &str,
    values: &[f64],
    expected_values: &[f64],
    grads: &[f64],
    expected_grads: &[f64],
    log: bool,
    floor: Option<&Floor>,
) {
    let ev = if log {
        log_err(values, expected_values)
    } else {
        rel_err(values, expected_values)
    };
    let eg = rel_err_atol(grads, expected_grads, GRAD_ATOL);
    let (tv, tg) = floor.map_or((VALUE_TOL, GRAD_TOL), |f| {
        (VALUE_TOL.max(10.0 * f.value), GRAD_TOL.max(10.0 * f.grad))
    });
    r.check(fixture, &format!("{label} value"), ev, tv);
    r.check(fixture, &format!("{label} gradient"), eg, tg);
}

/// Non-incremental qLogNEHVI is `log(NEHVI + prev_nehvi)` where the
/// improvement `prev_nehvi` of cached pending points is exact only to the
/// rounding of hypervolume differences (about 1e-15 of the hypervolume),
/// which the logarithm amplifies when the pending points add nothing: the
/// values are compared in linear space relative to the hypervolume, the
/// gradients as those of `exp(value)`.
#[allow(clippy::too_many_arguments)]
fn compare_linear(
    r: &mut Report,
    fixture: &str,
    label: &str,
    values: &[f64],
    expected_values: &[f64],
    grads: &[f64],
    expected_grads: &[f64],
    hv_scale: f64,
) {
    let ev = values
        .iter()
        .zip(expected_values)
        .map(|(a, e)| (a.exp() - e.exp()).abs() / hv_scale)
        .fold(0.0, f64::max);
    r.check(fixture, &format!("{label} value (linear)"), ev, EXACT_TOL);
    let per = grads.len() / values.len();
    let lin = |v: &[f64], g: &[f64]| -> Vec<f64> {
        g.iter()
            .enumerate()
            .map(|(i, g)| v[i / per].exp() * g)
            .collect()
    };
    let eg = rel_err_atol(
        &lin(values, grads),
        &lin(expected_values, expected_grads),
        GRAD_ATOL,
    );
    r.check(
        fixture,
        &format!("{label} gradient of exp(value)"),
        eg,
        GRAD_TOL,
    );
}

/// The NEHVI state accessors of qNEHVI and qLogNEHVI.
struct State {
    x_cached: Matrix,
    num_cells: usize,
    hypervolumes: Vec<f64>,
    baseline_hvs: Option<Vec<f64>>,
    prev_nehvi: f64,
}

enum Nehvi {
    Linear(QNoisyExpectedHypervolumeImprovement),
    Log(QLogNoisyExpectedHypervolumeImprovement),
}

impl Nehvi {
    fn acqf(&self) -> &dyn AcquisitionFunction {
        match self {
            Nehvi::Linear(a) => a,
            Nehvi::Log(a) => a,
        }
    }

    fn state(&self) -> State {
        macro_rules! state {
            ($a:expr) => {
                State {
                    x_cached: $a.x_baseline_and_pending(),
                    num_cells: $a.cell_bounds().num_cells(),
                    hypervolumes: $a.hypervolumes(),
                    baseline_hvs: $a.baseline_hvs(),
                    prev_nehvi: $a.prev_nehvi(),
                }
            };
        }
        match self {
            Nehvi::Linear(a) => state!(a),
            Nehvi::Log(a) => state!(a),
        }
    }
}

fn check_state(r: &mut Report, fixture: &str, label: &str, acqf: &Nehvi, e: &NehviState) {
    let s = acqf.state();
    let same_baseline = s.x_cached == matrix(&e.x_baseline);
    r.check(
        fixture,
        &format!("{label} cached baseline differs"),
        f64::from(u8::from(!same_baseline)),
        0.0,
    );
    r.check(
        fixture,
        &format!("{label} number of cells differs"),
        f64::from(u8::from(s.num_cells != e.num_cells)),
        0.0,
    );
    r.check_slices(
        fixture,
        &format!("{label} hypervolumes"),
        &s.hypervolumes,
        &vals(&e.hypervolumes),
        VALUE_TOL,
    );
    match (&s.baseline_hvs, &e.baseline_hvs) {
        (Some(a), Some(b)) => r.check_slices(
            fixture,
            &format!("{label} baseline hypervolumes"),
            a,
            &vals(b),
            VALUE_TOL,
        ),
        (None, None) => {}
        _ => r.check(
            fixture,
            &format!("{label} baseline hypervolumes present"),
            1.0,
            0.0,
        ),
    }
    // The improvement of cached pending points is a mean of differences of
    // hypervolumes, exact only to their rounding (pending points that add
    // nothing give 0 or about 1e-15 of the hypervolume in either library):
    // its error is relative to the hypervolume.
    let ep = e.prev_nehvi.0;
    let hv_scale = vals(&e.hypervolumes)
        .iter()
        .fold(ep.abs(), |m, v| m.max(v.abs()));
    let err = (s.prev_nehvi - ep).abs() / hv_scale.max(f64::MIN_POSITIVE);
    r.check(fixture, &format!("{label} previous NEHVI"), err, EXACT_TOL);
}

