#[test]
fn parity_multi_output_objectives() {
    let mut r = Report::default();
    for f in load() {
        let model = build_model(&f.kind, &f.models);
        let xb = matrix(&f.baseline_x);
        for c in &f.objectives {
            let (s, n, m) = (c.y.len(), c.y[0].len(), c.y[0][0].len());
            let y: Vec<f64> = c.y.iter().flatten().flatten().copied().collect();
            let samples = McSamples::from_row_major(&y, s, n, m).unwrap();
            let objective = build_objective(&c.objective, model.as_ref(), &xb);
            let out = objective.evaluate(&samples, None, false).unwrap();
            let label = format!("{:?}", c.objective)
                .split_whitespace()
                .next()
                .unwrap()
                .to_string();
            r.check(
                &f.name,
                &format!("objective {label}"),
                finite_err(&out.values.to_row_major(), &flat3(&c.values)),
                EXACT_TOL,
            );
            if let Some(cost) = &c.infeasible_cost {
                let feas = FeasibilityWeightedMcMultiOutputObjective::new(
                    model.as_ref(),
                    &xb,
                    &[-1],
                    None,
                )
                .unwrap();
                r.check_slices(
                    &f.name,
                    "infeasible cost",
                    feas.infeasible_cost(),
                    cost,
                    EXACT_TOL,
                );
            }
        }
    }
    r.finish("multi-output objectives");
}

#[test]
fn parity_qehvi_and_qlogehvi() {
    let mut r = Report::default();
    for f in load() {
        let model = build_model(&f.kind, &f.models);
        let xb = matrix(&f.baseline_x);
        for c in &f.ehvi {
            let part = partitioning(&c.partitioning, &c.ref_point, &matrix(&c.front), c.alpha);
            let cells = part.get_hypercell_bounds().expect("cell bounds");
            let label = format!(
                "{} q={} {} {}",
                if c.acqf.starts_with("qLog") {
                    "qLogEHVI"
                } else {
                    "qEHVI"
                },
                c.q,
                c.partitioning,
                c.objective
                    .as_ref()
                    .map_or("identity".to_string(), |o| format!("{o:?}")
                        .split_whitespace()
                        .next()
                        .unwrap()
                        .to_string()),
            );
            assert_eq!(
                cells.num_cells(),
                c.cell_shape[0],
                "{label}: number of cells"
            );
            r.check(
                &f.name,
                "EHVI cell lower bounds",
                finite_err(cells.lower(), &vals(&c.cell_lower)),
                EXACT_TOL,
            );
            r.check(
                &f.name,
                "EHVI cell upper bounds",
                finite_err(cells.upper(), &vals(&c.cell_upper)),
                EXACT_TOL,
            );
            let objective = objective_of(&c.objective, model.as_ref(), &xb);
            let constraints = constraints_of(&c.constraints, &c.eta);
            let pending = c.x_pending.as_ref().map(|p| matrix(p));
            let s = sampler(&f.draws, f.num_samples);
            let log = c.acqf.starts_with("qLog");
            let acqf: Box<dyn AcquisitionFunction> = if log {
                let mut options = QLogExpectedHypervolumeImprovementOptions {
                    sampler: Some(s),
                    objective,
                    constraints,
                    x_pending: pending,
                    fat: c.fat.unwrap_or(true),
                    ..Default::default()
                };
                if let Some(t) = c.tau_relu {
                    options.tau_relu = t;
                }
                Box::new(
                    QLogExpectedHypervolumeImprovement::new(
                        Arc::clone(&model),
                        &c.ref_point,
                        part.as_ref(),
                        options,
                    )
                    .unwrap(),
                )
            } else {
                Box::new(
                    QExpectedHypervolumeImprovement::new(
                        Arc::clone(&model),
                        &c.ref_point,
                        part.as_ref(),
                        QExpectedHypervolumeImprovementOptions {
                            sampler: Some(s),
                            objective,
                            constraints,
                            x_pending: pending,
                            fat: c.fat.unwrap_or(false),
                        },
                    )
                    .unwrap(),
                )
            };
            let (v, g) = evaluate(acqf.as_ref(), &c.x);
            compare(
                &mut r,
                &f.name,
                &label,
                &v,
                &vals(&c.values),
                &g,
                &flat3(&c.grads),
                log,
                None,
            );
        }
    }
    r.finish("qEHVI and qLogEHVI");
}

fn build_nehvi(f: &Fixture, model: &Arc<dyn Model>, xb: &Matrix, c: &NehviCase) -> Nehvi {
    let (n, m) = (xb.nrows(), model.num_outputs());
    let prune_options = PruneMultiObjectiveOptions {
        num_samples: f.prune_base_samples.len() / (n * m),
        base_samples: Some(Matrix::from_row_slice(
            f.prune_base_samples.len() / (n * m),
            n * m,
            &f.prune_base_samples,
        )),
        ..Default::default()
    };
    let objective = objective_of(&c.objective, model.as_ref(), xb);
    let constraints = constraints_of(&c.constraints, &c.eta);
    let pending = c.x_pending.as_ref().map(|p| matrix(p));
    let s = Some(sampler(&f.draws, f.num_samples));
    if c.log {
        Nehvi::Log(
            QLogNoisyExpectedHypervolumeImprovement::new(
                Arc::clone(model),
                &c.ref_point,
                xb,
                QLogNoisyExpectedHypervolumeImprovementOptions {
                    sampler: s,
                    objective,
                    constraints,
                    x_pending: pending,
                    prune_baseline: c.prune_baseline,
                    prune_options,
                    alpha: c.alpha,
                    max_iep: c.max_iep,
                    incremental_nehvi: c.incremental,
                    cache_root: c.cache_root,
                    ..Default::default()
                },
            )
            .unwrap(),
        )
    } else {
        Nehvi::Linear(
            QNoisyExpectedHypervolumeImprovement::new(
                Arc::clone(model),
                &c.ref_point,
                xb,
                QNoisyExpectedHypervolumeImprovementOptions {
                    sampler: s,
                    objective,
                    constraints,
                    x_pending: pending,
                    prune_baseline: c.prune_baseline,
                    prune_options,
                    alpha: c.alpha,
                    max_iep: c.max_iep,
                    incremental_nehvi: c.incremental,
                    cache_root: c.cache_root,
                    ..Default::default()
                },
            )
            .unwrap(),
        )
    }
}

#[test]
fn parity_qnehvi_and_qlognehvi() {
    let mut r = Report::default();
    for f in load() {
        let model = build_model(&f.kind, &f.models);
        let xb = matrix(&f.baseline_x);
        for c in &f.nehvi {
            let label = format!(
                "{} q={} cr={} inc={} P={}{}{}",
                if c.log { "qLogNEHVI" } else { "qNEHVI" },
                c.q,
                u8::from(c.cache_root),
                u8::from(c.incremental),
                c.x_pending.as_ref().map_or(0, Vec::len),
                if c.alpha > 0.0 { " alpha" } else { "" },
                if c.prune_baseline { " pruned" } else { "" },
            );
            let acqf = build_nehvi(&f, &model, &xb, c);
            let (v, g) = evaluate(acqf.acqf(), &c.x);
            compare(
                &mut r,
                &f.name,
                &label,
                &v,
                &vals(&c.values),
                &g,
                &flat3(&c.grads),
                c.log,
                Some(&c.floor),
            );
            check_state(&mut r, &f.name, &label, &acqf, &c.state);
        }
    }
    r.finish("qNEHVI and qLogNEHVI");
}

